def unsortedLength(nums):
    n = len(nums)
    end = -1
    mx = nums[0]
    for i in range(1, n):
        if nums[i] < mx:
            end = i
        else:
            mx = nums[i]
    if end == -1:
        return 0
    start = 0
    mn = nums[-1]
    for i in range(n - 2, -1, -1):
        if nums[i] > mn:
            start = i
        else:
            mn = nums[i]
    return end - start + 1
